head.script:
scwin.trigger1_onclick = function(e) {
    var info = {
        inputType: "text",
        value: grid1.getCellData(0, 2),
        options: {
            dataType: "number",
            displayFormat: "#,##0.##0%"
        }
    };
    grid1.setCellInputType(0, 2, info);
    var options = {
        common: {
            fileName: "excel.xlsx",
            showProcess: true,
            useStyle: "true",
            //useDataFormat:"true",
            printSet: {
                landScape: "true",
                fitToPage: "true",
                fitWidth: "4",
                fitHeight: "333",
                scale: "222"
            }
        },
        excelInfo: [{
            gridId: "grid1",
            sheetName: "sheetName1",
            type: "1",
            //removeColumns: "0,2",
            //foldColumns: "4",
            startRowIndex: 2,
            startColumnIndex: 1,
            //dataProvider: "com.provider.Provider1",
            headerColor: "RED",
            bodyColor: "YELLOW",
            //providerRequestXml: "",
            infoArr: [{
                rowIndex: 1,
                colIndex: 6,
                rowSpan: 2,
                colSpan: 2,
                text: "데이터표시1",
                textAlign: "right"
            }]
        }, {
            gridId: "grid2",
            sheetName: "sheetName2",
            type: "1",
            //removeColumns: "",
            //foldColumns: "4",
            startRowIndex: 2,
            startColumnIndex: 1,
            //dataProvider: "com.provider.Provider1",
            headerColor: "GREEN",
            bodyColor: "BLUE",
            //providerRequestXml: "",
            infoArr: [{
                rowIndex: 1,
                colIndex: 6,
                rowSpan: 2,
                colSpan: 2,
                text: "데이터표시2",
                textAlign: "right"
            }]
        }]
    };
    WebSquare.util.multipleExcelDownload(options);
};
scwin.trigger2_onclick = function(e) {
    var info = {
        inputType: "text",
        value: grid1.getCellData(0, 2),
        options: {
            dataType: "number",
            displayFormat: "#,##0.##0%"
        }
    };
    grid1.setCellInputType(0, 2, info);
    grid1.advancedExcelDownload({
        type: "1",
        fileName: "aaa.xlsx",
        useStyle: "true"
    });
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
